export function buildPage<T>(items: T[], total: number, page: number, pageSize: number): Page<T> {
  return {
    items,
    total,
    page,
    pageSize,
    pageCount: pageSize > 0 ? Math.ceil(total / pageSize) : 0,
  };
}

export function canTransition(from: TaskStatus, to: TaskStatus): boolean {
  return TRANSITIONS[from].includes(to);
}

export function allowedTransitions(from: TaskStatus): readonly TaskStatus[] {
  return TRANSITIONS[from];
}

export class IllegalStatusTransitionError extends DomainError {
  constructor(from: string, to: string) {
    super(`Cannot move task from '${from}' to '${to}'`, 409, 'ILLEGAL_STATUS_TRANSITION');
  }
}
